import{_ as t,o as a,c as d,a0 as o}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"Design System","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/design-system.md","filePath":"architecture/design-system.md"}'),n={name:"architecture/design-system.md"};function r(i,e,s,c,h,l){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="design-system" tabindex="-1">Design System <a class="header-anchor" href="#design-system" aria-label="Permalink to &quot;Design System&quot;">​</a></h1><h2 id="direction" tabindex="-1">Direction <a class="header-anchor" href="#direction" aria-label="Permalink to &quot;Direction&quot;">​</a></h2><p>UX patterns inspired by consumer fintech apps (clear progressive steps, card-based transaction history, confirmation-first flows), kept clear about scope: this is pattern inspiration, not a pixel-verified clone of any specific app, since no design tokens were extracted from a live reference. The brand&#39;s own accent, a restrained indigo-violet, replaced an earlier green palette that read as generic/templated rather than banking-grade.</p><h2 id="color-tokens" tabindex="-1">Color tokens <a class="header-anchor" href="#color-tokens" aria-label="Permalink to &quot;Color tokens&quot;">​</a></h2><p>Defined once in <code>tailwind.config.js</code> and <code>index.css</code>; every component consumes the token, not a hardcoded hex value.</p><table tabindex="0"><thead><tr><th>Token</th><th>Dark (default)</th><th>Purpose</th></tr></thead><tbody><tr><td><code>brand-500</code></td><td><code>#6c56e3</code></td><td>Primary actions, links, brand mark</td></tr><tr><td><code>success-500</code></td><td><code>#3d7ee8</code></td><td>Verified/compliant states, a professional <strong>blue</strong>, not green, matching real banking &quot;verified&quot; badges</td></tr><tr><td><code>navy-950</code> / <code>--canvas</code></td><td>near-black</td><td>Page background</td></tr><tr><td><code>--surface</code></td><td><code>#12141b</code></td><td>Card/panel background</td></tr><tr><td><code>--ink</code> / <code>--ink-muted</code></td><td>near-white / grey</td><td>Primary / secondary text</td></tr></tbody></table><h2 id="light-mode" tabindex="-1">Light mode <a class="header-anchor" href="#light-mode" aria-label="Permalink to &quot;Light mode&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[html, no class] --&gt;|default| B[Dark, always tested]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt;|.light class toggled by ThemeToggle| C[Light, semantic tokens override]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;--canvas: #f7f7fb&lt;br/&gt;--surface: #ffffff&lt;br/&gt;--ink: #14161b&quot;]</span></span></code></pre></div><p>Implementation: <code>ThemeToggle.jsx</code> toggles a <code>.light</code> class on <code>&lt;html&gt;</code> and persists the choice in <code>localStorage</code>. Rather than prefixing every utility class with <code>dark:</code> across ~25 components (a much larger undertaking), semantic CSS-variable tokens (<code>bg-canvas</code>, <code>bg-surface</code>, <code>text-ink</code>, <code>text-ink-muted</code>, <code>border-hairline</code>) were introduced and applied to the highest-traffic surfaces first, <strong>Navbar, Footer, and the Home page</strong>, verified by screenshot in both modes. The hero section deliberately keeps its own dark gradient in both modes (a common, legitimate &quot;dark hero over a light page&quot; pattern); its text is intentionally left as literal white rather than tied to the theme token, since the section&#39;s background doesn&#39;t change with it.</p><h2 id="what-changed-and-why" tabindex="-1">What changed and why <a class="header-anchor" href="#what-changed-and-why" aria-label="Permalink to &quot;What changed and why&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Before</th><th>After</th><th>Why</th></tr></thead><tbody><tr><td>Green accent (<code>brand</code>, <code>success</code>, plus 8 hardcoded hex values in <code>index.css</code>)</td><td>Indigo-violet accent throughout</td><td>Read as a generic AI/crypto template; a single restrained accent is closer to real banking-app convention</td></tr><tr><td>&quot;Verified&quot; = green</td><td>&quot;Verified&quot; = blue</td><td>Matches how banks and platforms (e.g. verified-account badges) typically signal trust, green was overloaded with the brand color it&#39;s now separate from</td></tr><tr><td>No light mode</td><td>Toggleable light mode on primary surfaces</td><td>Requested; implemented as a real, screenshot-verified feature rather than a superficial CSS filter</td></tr></tbody></table>`,11)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
